outputs.matlab:
function output = heartlib(a)
% output = heartlib(a)
%
%    b = min_(i ∈ ℝ) 3i+a
%            s.t.
%            i > 4
%            i < 9 
%            where 
%            a: scalar 
    assert(numel(a) == 1);

    % b = min_(i ∈ ℝ) 3i+a
    %         s.t.
    %         i > 4
    %         i < 9 

    i = optimvar('i');
    prob = optimproblem;
    prob.Constraints.cons1 = i >= 4;
    prob.Constraints.cons2 = i <= 9;
    prob.Objective = 3 * i + a;
    [~, optimize] = solve(prob);
    b = optimize;
    output.b = b;
    output.a = a;
end

